#####################################################################################
# Project: Coffee Rhizosphere Microbiome - 16S rRNA Metabarcoding
# Script: 05_beta_diversity.R
# Author: Gustavo Goncalves
# Last edit: 18/11/2026
#
# Description:
# Exploratory analysis of beta diversity in coffee rhizosphere microbiome samples,
# including Bray-Curtis dissimilarity, PCoA ordination, PERMANOVA, and
# beta-dispersion analysis.
#
# Notes:
#   This script requires the phyloseq object generated by 03_phyloseq_object.R.
#####################################################################################

# Load project configuration
source("projects/coffee/config.R")

# Set up packages
library(phyloseq); packageVersion("phyloseq")
library(ggplot2); packageVersion("ggplot2")
library(vegan); packageVersion("vegan")

theme_set(theme_bw())

# Create beta diversity directory
beta_path <- file.path(results_path, "beta_diversity")
dir.create(beta_path, recursive = TRUE, showWarnings = FALSE)

# Load phyloseq object
ps <- readRDS(file.path(objects_path, "phyloseq_object.rds"))


#####################################################################################
# Bray-Curtis dissimilarity
#####################################################################################

bray <- phyloseq::distance(
  physeq = ps,
  method = "bray"
)

# Extract sample metadata in the same order as the distance matrix
metadata <- data.frame(sample_data(ps))
metadata <- metadata[labels(bray), , drop = FALSE]


#####################################################################################
# PCoA ordination
#####################################################################################

ord.pcoa <- ordinate(
  ps,
  method = "PCoA",
  distance = bray
)

# Plot by CropStage
p1 <- plot_ordination(
  ps,
  ord.pcoa,
  color = "CropStage"
) +
  geom_point(size = 3)

print(p1)

ggsave(
  filename = file.path(beta_path, "pcoa_cropstage.png"),
  plot = p1,
  width = 8,
  height = 6,
  dpi = 300
)


# Plot by Quality
p2 <- plot_ordination(
  ps,
  ord.pcoa,
  color = "Quality"
) +
  geom_point(size = 3)

print(p2)

ggsave(
  filename = file.path(beta_path, "pcoa_quality.png"),
  plot = p2,
  width = 8,
  height = 6,
  dpi = 300
)


# Plot by Farm
p3 <- plot_ordination(
  ps,
  ord.pcoa,
  color = "Farm"
) +
  geom_point(size = 3)

print(p3)

ggsave(
  filename = file.path(beta_path, "pcoa_farm.png"),
  plot = p3,
  width = 8,
  height = 6,
  dpi = 300
)


# Plot by Farm with group ellipses
p4 <- plot_ordination(
  ps,
  ord.pcoa,
  color = "Farm"
) +
  geom_point(size = 3) +
  stat_ellipse()

print(p4)

ggsave(
  filename = file.path(beta_path, "pcoa_farm_ellipses.png"),
  plot = p4,
  width = 8,
  height = 6,
  dpi = 300
)


#####################################################################################
# PERMANOVA
#####################################################################################

# Individual effects
perm.farm <- adonis2(
  bray ~ Farm,
  data = metadata,
  permutations = 999
)

perm.cropstage <- adonis2(
  bray ~ CropStage,
  data = metadata,
  permutations = 999
)

perm.quality <- adonis2(
  bray ~ Quality,
  data = metadata,
  permutations = 999
)

# Marginal effects
perm.marginal <- adonis2(
  bray ~ Farm + CropStage + Quality,
  data = metadata,
  permutations = 999,
  by = "margin"
)

# Display results
print(perm.farm)
print(perm.cropstage)
print(perm.quality)
print(perm.marginal)

# Save PERMANOVA results
sink(file.path(beta_path, "permanova_results.txt"))

cat("PERMANOVA - Farm\n")
print(perm.farm)

cat("\nPERMANOVA - CropStage\n")
print(perm.cropstage)

cat("\nPERMANOVA - Quality\n")
print(perm.quality)

cat("\nPERMANOVA - Marginal effects\n")
print(perm.marginal)

sink()


#####################################################################################
# Beta-dispersion
#####################################################################################

# Test homogeneity of multivariate dispersion among farms
disp.farm <- betadisper(
  bray,
  metadata$Farm
)

disp.test <- permutest(
  disp.farm,
  permutations = 999
)

# Pairwise comparisons among farms
disp.tukey <- TukeyHSD(disp.farm)

# Display results
print(disp.test)
print(disp.tukey)

# Save beta-dispersion results
sink(file.path(beta_path, "betadisper_results.txt"))

cat("Beta-dispersion - Farm\n\n")
print(disp.test)

cat("\nPairwise comparisons - TukeyHSD\n\n")
print(disp.tukey)

sink()

# Visualize beta-dispersion
png(
  filename = file.path(beta_path, "betadisper_farm.png"),
  width = 2400,
  height = 1800,
  res = 300
)

boxplot(
  disp.farm,
  main = "Beta-dispersion by Farm",
  xlab = "Farm",
  ylab = "Distance to centroid"
)

dev.off()


#####################################################################################
# End
#####################################################################################
